/**
 * Collect the Python the browser's scoring worker needs into one JSON file.
 *
 *   node scripts/build-py-bundle.mjs        (runs automatically before dev and build)
 *
 * Everything under core/ and config/ goes in unchanged — the whole point is that the code
 * scoring in React IS the code scoring in Streamlit — plus the two stand-ins from
 * web/python/ that replace the database layer (see their docstrings).
 *
 * The result goes to public/py/bundle.json, which is fetched once by the worker and then
 * cached by the browser. It is NOT imported into the app bundle: 2 MB of Python has no
 * business in the JavaScript every page downloads.
 */
import { createHash } from "node:crypto";
import { copyFileSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const web = path.resolve(here, "..");
const root = path.resolve(web, "..");

function walk(dir, keep, out = []) {
  for (const name of readdirSync(dir)) {
    if (name === "__pycache__") continue;
    const p = path.join(dir, name);
    if (statSync(p).isDirectory()) walk(p, keep, out);
    else if (keep(name)) out.push(p);
  }
  return out;
}

const files = {};
const put = (as, src) => {
  files[as.split(path.sep).join("/")] = src;
};

for (const f of walk(path.join(root, "core"), (n) => n.endsWith(".py"))) {
  put(path.relative(root, f), readFileSync(f, "utf8"));
}
for (const f of walk(path.join(root, "config"), (n) => /\.ya?ml$/.test(n))) {
  put(path.relative(root, f), readFileSync(f, "utf8"));
}
// The stand-ins, mounted where the real modules would be so imports resolve to them.
put("db/supabase_client.py", readFileSync(path.join(web, "python/supabase_client_stub.py"), "utf8"));
put("auth/tenant_context.py", readFileSync(path.join(web, "python/tenant_context_stub.py"), "utf8"));
put("db/__init__.py", "");
put("auth/__init__.py", "");

const json = JSON.stringify(files);
const hash = createHash("sha256").update(json).digest("hex").slice(0, 12);
mkdirSync(path.join(web, "public/py"), { recursive: true });
writeFileSync(path.join(web, "public/py/bundle.json"), json);
// The worker asks for the bundle by hash, so a deploy can never serve yesterday's Python
// from a cache alongside today's app.
writeFileSync(path.join(web, "src/generated/py-bundle-hash.ts"),
  `// Generated by scripts/build-py-bundle.mjs — do not edit.\nexport const PY_BUNDLE_HASH = "${hash}";\n`);
console.log(`py bundle: ${Object.keys(files).length} files, ${(json.length / 1e6).toFixed(1)} MB, hash ${hash}`);

// The user manual and training deck, offered on Home and Help exactly as Streamlit offers
// them. Copied rather than committed twice: assets/help/ is the one source.
const helpSrc = path.join(root, "assets/help");
const helpOut = path.join(web, "public/help");
mkdirSync(helpOut, { recursive: true });
for (const name of readdirSync(helpSrc)) {
  copyFileSync(path.join(helpSrc, name), path.join(helpOut, name));
}
console.log(`help assets: ${readdirSync(helpSrc).join(", ")}`);
